// PL_Validate_Input — validates the OR-01 handoff envelope
// Reference contract: 06_STAGE_WF-PL-01.md §Input contract
//
// Strategy: fail fast on missing top-level / intent / orchestrator_decision fields.
// Output shape: { ...input, _valid: boolean, _validation_errors: [string] }

const CANONICAL_MODULES = new Set([
  'task_module',
  'reminder_module',
  'memory_module',
  'improvement_module',
  'response_support_module'
]);

const items = $input.all();
const out = [];

for (const it of items) {
  const j = it.json || {};
  const errors = [];

  if (!j.execution_id) errors.push('missing execution_id');
  if (!j.tenant_id) errors.push('missing tenant_id');
  if (!j.thread_id) errors.push('missing thread_id');
  if (!j.idempotency_key) errors.push('missing idempotency_key');

  const intent = j.intent || {};
  if (!Array.isArray(intent.required_modules) || intent.required_modules.length === 0) {
    errors.push('intent.required_modules must be non-empty array');
  } else {
    for (const m of intent.required_modules) {
      if (!CANONICAL_MODULES.has(m)) {
        errors.push('intent.required_modules contains non-canonical module: ' + m);
      }
    }
  }

  const od = j.orchestrator_decision || {};
  if (!Array.isArray(od.module_order) || od.module_order.length === 0) {
    errors.push('orchestrator_decision.module_order must be non-empty array');
  } else {
    for (const m of od.module_order) {
      if (!CANONICAL_MODULES.has(m)) {
        errors.push('orchestrator_decision.module_order contains non-canonical module: ' + m);
      }
    }
  }

  out.push({
    json: {
      ...j,
      _valid: errors.length === 0,
      _validation_errors: errors,
      _validation_stage: 'input'
    }
  });
}

return out;

// PL_Build_Plan_Envelope — deterministic envelope construction
// Reference: 06_STAGE_WF-PL-01.md §Output contract, §Recommended node layout step 4
//
// Strategy:
//  - walk orchestrator_decision.module_order
//  - assign stable step_id = `step_<module>_<ordinal>`
//  - derive expected_side_effect.surface from MODULE_SURFACE_MAP
//  - copy dependency_graph into per-step depends_on[]
//  - set status='planned'
//
// Pure-logic parity: see workflows/scripts/pl/pl_logic.py::build_plan_envelope()

const crypto = require('crypto');

const MODULE_SURFACE_MAP = {
  task_module: { surface: 'tasks', write_class: 'create' },
  reminder_module: { surface: 'reminders', write_class: 'create' },
  memory_module: { surface: 'rag_memories', write_class: 'create' },
  improvement_module: { surface: 'execution_contexts', write_class: 'update' },
  response_support_module: { surface: 'none', write_class: 'none' }
};

const items = $input.all();
const out = [];

for (const it of items) {
  const j = it.json || {};
  const od = j.orchestrator_decision || {};
  const module_order = od.module_order || [];
  const dep_graph = od.dependency_graph || {};

  // step_id derivation: stable within plan
  const ord_counter = {};
  const module_to_stepid = {};
  const steps = [];

  for (const mod of module_order) {
    const ord = (ord_counter[mod] || 0) + 1;
    ord_counter[mod] = ord;
    const step_id = 'step_' + mod + '_' + ord;
    module_to_stepid[mod] = step_id;

    const surface_info = MODULE_SURFACE_MAP[mod] || { surface: 'none', write_class: 'none' };

    steps.push({
      step_id: step_id,
      target_module: mod,
      action_type: (j.intent && j.intent.action_type_hints && j.intent.action_type_hints[mod]) || 'execute',
      depends_on: [], // resolved below
      expected_side_effect: {
        surface: surface_info.surface,
        write_class: surface_info.write_class,
        idempotency_key_hint: j.idempotency_key + ':' + step_id
      },
      status: 'planned'
    });
  }

  // Resolve depends_on: graph maps module -> [dependency modules]
  for (const step of steps) {
    const deps = dep_graph[step.target_module] || [];
    step.depends_on = deps.map((d) => module_to_stepid[d]).filter(Boolean);
  }

  // plan_id: deterministic from (execution_id, idempotency_key)
  const plan_id_src = (j.execution_id || '') + ':' + (j.idempotency_key || '');
  const hash = crypto.createHash('sha256').update(plan_id_src).digest('hex');
  // Format as UUID-ish (not RFC 4122 strict, but deterministic and unique per input)
  const plan_id = [hash.slice(0, 8), hash.slice(8, 12), '4' + hash.slice(13, 16), '8' + hash.slice(17, 20), hash.slice(20, 32)].join('-');

  out.push({
    json: {
      ...j,
      _plan_envelope: {
        plan_id: plan_id,
        execution_id: j.execution_id,
        tenant_id: j.tenant_id,
        thread_id: j.thread_id,
        status: 'planned',
        steps: steps,
        plan_envelope_version: 'pl-01.v1',
        created_at: new Date().toISOString()
      }
    }
  });
}

return out;

// PL_Validate_Plan_Envelope — structural + graph + privacy checks
// Reference: 06_STAGE_WF-PL-01.md §Recommended node layout step 5, §V3/V4
//
// Strategy: 4 structural checks + populate validation{}
//   (a) no cycles in dependency graph
//   (b) every depends_on step_id exists
//   (c) all target_module values ∈ CANONICAL_MODULES
//   (d) privacy pre-flight: no response_support_module without upstream producing module
//
// Pure-logic parity: workflows/scripts/pl/pl_logic.py::validate_plan_envelope()

const CANONICAL_MODULES = new Set([
  'task_module', 'reminder_module', 'memory_module', 'improvement_module', 'response_support_module'
]);
const PRODUCING_MODULES = new Set(['task_module', 'reminder_module', 'memory_module', 'improvement_module']);

function hasCycle(steps) {
  // DFS with coloring: WHITE=0 GRAY=1 BLACK=2
  const color = {};
  const byId = {};
  for (const s of steps) { color[s.step_id] = 0; byId[s.step_id] = s; }

  function dfs(id) {
    if (color[id] === 1) return true;
    if (color[id] === 2) return false;
    color[id] = 1;
    const s = byId[id];
    if (s) {
      for (const dep of (s.depends_on || [])) {
        if (dfs(dep)) return true;
      }
    }
    color[id] = 2;
    return false;
  }
  for (const s of steps) {
    if (color[s.step_id] === 0 && dfs(s.step_id)) return true;
  }
  return false;
}

const items = $input.all();
const out = [];

for (const it of items) {
  const j = it.json || {};
  const env = j._plan_envelope || {};
  const steps = env.steps || [];

  const step_ids = new Set(steps.map((s) => s.step_id));
  let all_refs_exist = true;
  for (const s of steps) {
    for (const d of (s.depends_on || [])) {
      if (!step_ids.has(d)) { all_refs_exist = false; break; }
    }
    if (!all_refs_exist) break;
  }

  const module_set_permitted = steps.every((s) => CANONICAL_MODULES.has(s.target_module));
  const no_cycles = !hasCycle(steps);

  // Privacy pre-flight
  const has_response_support = steps.some((s) => s.target_module === 'response_support_module');
  const has_producer = steps.some((s) => PRODUCING_MODULES.has(s.target_module));
  const privacy_preflight_ok = !has_response_support || has_producer;

  const graph_valid = all_refs_exist && no_cycles && module_set_permitted;

  const validation = {
    graph_valid: graph_valid,
    no_cycles: no_cycles,
    module_set_permitted: module_set_permitted,
    privacy_preflight_ok: privacy_preflight_ok,
    all_refs_exist: all_refs_exist
  };

  const envelope_valid = graph_valid && privacy_preflight_ok;

  out.push({
    json: {
      ...j,
      _plan_envelope: { ...env, validation: validation },
      _envelope_valid: envelope_valid,
      _envelope_validation_errors: envelope_valid ? [] : [
        !no_cycles ? 'graph_cycle' : null,
        !module_set_permitted ? 'module_not_permitted' : null,
        !all_refs_exist ? 'dangling_dependency' : null,
        !privacy_preflight_ok ? 'privacy_gate_failed' : null
      ].filter(Boolean)
    }
  });
}

return out;

// PL_Return_Result — shape the final output contract
// Reference: 06_STAGE_WF-PL-01.md §Output contract
//
// Strategy: combine upsert row + in-memory envelope, set replayed flag

const items = $input.all();
const out = [];

for (const it of items) {
  const j = it.json || {};
  // Upstream Postgres node returned the row as $json (first and only row)
  const envelope = j._plan_envelope || {};
  const replayed = (j.replayed === true || j.replayed === 't');

  out.push({
    json: {
      plan_id: j.id || envelope.plan_id,
      execution_id: j.execution_id || envelope.execution_id,
      tenant_id: j.tenant_id || envelope.tenant_id,
      thread_id: j.thread_id || envelope.thread_id,
      status: j.status || envelope.status || 'planned',
      steps: envelope.steps || (typeof j.steps === 'string' ? JSON.parse(j.steps) : j.steps) || [],
      validation: envelope.validation || (typeof j.validation === 'string' ? JSON.parse(j.validation) : j.validation) || {},
      plan_envelope_version: envelope.plan_envelope_version || j.plan_envelope_version || 'pl-01.v1',
      created_at: j.created_at || envelope.created_at,
      replayed: replayed
    }
  });
}

return out;

// PL_Return_Error — structured error envelope
// Reference: 06_STAGE_WF-PL-01.md §Recommended node layout step 7 (PL_Return_Error)

const items = $input.all();
const out = [];

for (const it of items) {
  const j = it.json || {};
  const input_errors = j._validation_errors || [];
  const envelope_errors = j._envelope_validation_errors || [];
  const all_errors = [...input_errors, ...envelope_errors];

  let failure_class = 'invalid_input';
  if (envelope_errors.includes('graph_cycle')) failure_class = 'graph_cycle';
  else if (envelope_errors.includes('module_not_permitted')) failure_class = 'module_not_permitted';
  else if (envelope_errors.includes('privacy_gate_failed')) failure_class = 'privacy_gate_failed';
  else if (envelope_errors.includes('dangling_dependency')) failure_class = 'dangling_dependency';

  out.push({
    json: {
      success: false,
      failure_class: failure_class,
      errors: all_errors,
      execution_id: j.execution_id || null,
      tenant_id: j.tenant_id || null,
      thread_id: j.thread_id || null,
      idempotency_key: j.idempotency_key || null,
      emitted_at: new Date().toISOString()
    }
  });
}

return out;
